// swift-tools-version:6.0
// earshot app. The probe (../probe) stays as the lab for experiments.
// Each module depends on EarshotCore only, and talks to the others through its protocols.
// Only EarshotApp depends on all modules. Language mode: Swift 5 (see docs/BUILD-PLAN.md).
// Threads do not edit this file. The exceptions: T1 adds the TranscribeCpp binary target and its linker settings,
// the Intel port sets the platform to macOS 14 (only EarshotSpeech/AppleSpeechEngine.swift needs macOS 26, behind @available),
// and the wake phrase change (D-11) adds the EarshotWake module (Core ML keyword spotter and voice model).
import PackageDescription

let modules = ["EarshotSpeech", "EarshotRouter", "EarshotActions", "EarshotDiscovery", "EarshotInput", "EarshotUI", "EarshotWake"]

// T1: transcribe.cpp runs the Parakeet model (E2). Only EarshotSpeech uses it.
// CTranscribe is a dynamic framework. SwiftPM copies it next to the product.
// SwiftPM adds "@loader_path" (the tool) and "@loader_path/../../.." (test bundles) itself. Adding them again makes the linker warn.
// This list adds only Contents/Frameworks of the app bundle.
let transcribeSearchPaths = ["@executable_path/../Frameworks"]
let extraDependencies: [String: [Target.Dependency]] = ["EarshotSpeech": ["TranscribeCpp"]]
let extraLinker: [String: [LinkerSetting]] = [
    "EarshotSpeech": [
        .linkedLibrary("c++"),
        .linkedLibrary("z"),
        .linkedFramework("Accelerate"),
        .linkedFramework("Metal"),
        .linkedFramework("MetalKit"),
        .unsafeFlags(transcribeSearchPaths.flatMap { ["-Xlinker", "-rpath", "-Xlinker", $0] }),
    ],
]

// The targets are built in parts with explicit types. As one expression, the list took too long to type-check
// for Swift 6.1 (Command Line Tools on an Intel Mac): "unable to type-check this expression in reasonable time".
var targets: [Target] = [
    .target(name: "EarshotCore", path: "Sources/EarshotCore"),
    .testTarget(name: "EarshotCoreTests", dependencies: ["EarshotCore"], path: "Tests/EarshotCoreTests"),
]
let moduleDependencies: [Target.Dependency] = modules.map { .target(name: $0) }
let appDependencies: [Target.Dependency] = ["EarshotCore"] + moduleDependencies
targets.append(.executableTarget(name: "EarshotApp", dependencies: appDependencies, path: "Sources/EarshotApp"))
// T7: tests of the command path in EarshotApp, with fake engines and runners.
let appTestDependencies: [Target.Dependency] = ["EarshotApp", "EarshotCore"] + moduleDependencies
targets.append(.testTarget(name: "EarshotAppTests", dependencies: appTestDependencies, path: "Tests/EarshotAppTests"))
// transcribe.cpp 0.4.1 (MIT), prebuilt for Apple platforms. SwiftPM checks the SHA-256 sum of the file.
// From 0.4.0 it maps the model file by default, so the weights are clean file pages and not app memory.
targets.append(.binaryTarget(
    name: "TranscribeCpp",
    url: "https://github.com/handy-computer/transcribe.cpp/releases/download/v0.4.1/TranscribeCpp.xcframework.zip",
    checksum: "fb5646e564036a6c49659e3efcf72eb567af20da31b8569045c9a08181d35126"
))
for name in modules {
    let deps: [Target.Dependency] = ["EarshotCore"] + (extraDependencies[name] ?? [])
    let linker: [LinkerSetting] = extraLinker[name] ?? []
    targets.append(.target(name: name, dependencies: deps, path: "Sources/\(name)", linkerSettings: linker))
}
for name in modules {
    let deps: [Target.Dependency] = [.target(name: name), "EarshotCore"]
    targets.append(.testTarget(name: "\(name)Tests", dependencies: deps, path: "Tests/\(name)Tests"))
}

let package = Package(
    name: "earshot",
    platforms: [.macOS("14.0")],
    products: [
        .executable(name: "earshot", targets: ["EarshotApp"]),
        .library(name: "EarshotCore", targets: ["EarshotCore"]),
    ],
    targets: targets,
    swiftLanguageModes: [.v5]
)
